+Flags::Flags(QObject *parent)
+    : QObject(parent)
+    , m_configWatcher(KConfigWatcher::create(KSharedConfig::openConfig(QStringLiteral("kxkbrc"), KConfig::NoGlobals)))
+{
+    connect(m_configWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.name() == QLatin1String("Layout")) {
+            loadLayoutFlags();
+        }
+    });
+    loadLayoutFlags();
+}
+
 QIcon Flags::getIcon(const QString &layout)
 {
     if (!iconMap.contains(layout)) {
@@ -28,6 +45,43 @@ QIcon Flags::getIcon(const QString &layout)
     return iconMap[layout];
 }

+QStringList Flags::layoutFlags() const
+{
+    return m_layoutFlags;
+}
+
+void Flags::loadLayoutFlags()
+{
+    const KConfigGroup group = m_configWatcher->config()->group(QStringLiteral("Layout"));
+    const QStringList layouts = group.readEntry("LayoutList", QStringList());
+    QStringList flags = group.readEntry("Flags", QStringList());
+
+    if (flags.size() != layouts.size()) {
+        flags.clear();
+    }
+
+    if (flags != m_layoutFlags) {
+        m_layoutFlags = flags;
+        Q_EMIT layoutFlagsChanged();
+    }
+}
+
+QVariantList Flags::countries() const
+{
+    QList<KCountry> countries = KCountry::allCountries();
+    QCollator collator;
+    std::sort(countries.begin(), countries.end(), [&collator](const KCountry &a, const KCountry &b) {
+        return collator.compare(a.name(), b.name()) < 0;
+    });
+
+    QVariantList result;
+    result.reserve(countries.size());
+    for (const KCountry &country : std::as_const(countries)) {
+        result.append(QVariantMap{{QStringLiteral("code"), country.alpha2().toLower()}, {QStringLiteral("name"), country.name()}});
+    }
+    return result;
+}
+
 QIcon Flags::createIcon(const QString &layout)
 {
     return QIcon(new KCountryFlagEmojiIconEngine(getCountryFromLayoutName(layout)));
