+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Controls as QQC2
+
+import org.kde.kirigami as Kirigami
+
+import org.kde.plasma.private.kcm_keyboard as KCMKeyboard
+
+Kirigami.SearchDialog {
+    id: dialog
+
+    required property string layout
+
+    signal flagSelected(string flag)
+
+    readonly property var countries: [{
+        code: "",
+        name: i18nc("@item:inlistbox use the flag that matches the keyboard layout", "Default")
+    }].concat(KCMKeyboard.Flags.countries())
+
+    searchFieldPlaceholderText: i18nc("@info:placeholder", "Search flags…")
+    emptyText: i18nc("@info:placeholder", "No flags found")
+
+    model: countries.filter(country => country.name.toLowerCase().includes(text.toLowerCase()))
+
+    onAccepted: currentItem?.clicked()
+
+    delegate: QQC2.ItemDelegate {
+        id: delegate
+
+        required property var modelData
+        required property int index
+
+        width: ListView.view.width
+        highlighted: ListView.isCurrentItem
+
+        text: modelData.name
+
+        contentItem: Kirigami.IconTitleSubtitle {
+            icon.source: KCMKeyboard.Flags.getIcon(delegate.modelData.code || dialog.layout)
+            title: delegate.text
+        }
+
+        onClicked: {
+            dialog.flagSelected(delegate.modelData.code);
+            dialog.close();
+        }
+    }
+}
